package walker

import (
	"os"
	"os/exec"
	"path/filepath"
	"testing"
)

func TestWalkResolvesContentBasenamesAndShebangsWithoutGuessing(t *testing.T) {
	root := t.TempDir()
	fixtures := map[string]string{
		"proof.v":      "Require Import Arith.\nTheorem target : forall n : nat, n = n.\nProof. Qed.\n",
		"adder.v":      "module adder(input a, output b); assign b = a; endmodule\n",
		"ambiguous.v":  "(* no language-bearing declaration *)\n",
		"nginx.conf":   "server { listen 8080; }\n",
		"generic.conf": "key=value\n",
		"Makefile":     "all: build\nbuild:\n\t@true\n",
		"script":       "#!/usr/bin/env python3\nprint('ok')\n",
		"plain-binary": "not a shebang script\n",
	}
	for name, source := range fixtures {
		if err := os.WriteFile(filepath.Join(root, name), []byte(source), 0o600); err != nil {
			t.Fatal(err)
		}
	}
	files, err := Walk(root, 100)
	if err != nil {
		t.Fatal(err)
	}
	languages := map[string]string{}
	for _, file := range files {
		languages[file.Path] = file.Language
	}
	for path, want := range map[string]string{
		"proof.v": "coq", "adder.v": "verilog", "nginx.conf": "nginx",
		"Makefile": "make", "script": "python",
	} {
		if languages[path] != want {
			t.Fatalf("%s resolved as %q, want %q (all=%v)", path, languages[path], want, languages)
		}
	}
	for _, path := range []string{"ambiguous.v", "generic.conf", "plain-binary"} {
		if _, present := languages[path]; present {
			t.Fatalf("%s must abstain, got %q", path, languages[path])
		}
	}
}

func TestWalkZeroLimitIsUnlimitedAndPositiveLimitReportsEveryEligibleSkip(t *testing.T) {
	root := t.TempDir()
	for _, name := range []string{"a.py", "b.py", "c.py"} {
		if err := os.WriteFile(filepath.Join(root, name), []byte("value = 1\n"), 0o600); err != nil {
			t.Fatal(err)
		}
	}
	unlimited, err := WalkWithMeta(root, 0)
	if err != nil {
		t.Fatal(err)
	}
	if len(unlimited.Files) != 3 || unlimited.FilesSkipped != 0 {
		t.Fatalf("unlimited walk = %d indexed/%d skipped, want 3/0", len(unlimited.Files), unlimited.FilesSkipped)
	}
	limited, err := WalkWithMeta(root, 1)
	if err != nil {
		t.Fatal(err)
	}
	if len(limited.Files) != 1 || limited.FilesSkipped != 2 {
		t.Fatalf("limited walk = %d indexed/%d skipped, want 1/2", len(limited.Files), limited.FilesSkipped)
	}
}

func TestWalkUsesGitRealityAndDoesNotDropTrackedDotOrVendorDirectories(t *testing.T) {
	root := t.TempDir()
	fixtures := map[string]string{
		".gitignore":             "ignored.py\n",
		".github/workflow.yml":   "name: graph-receipt\n",
		"ignored.py":             "ignored = True\n",
		"visible.py":             "visible = True\n",
		"vendor/product/main.go": "package product\nfunc Main() {}\n",
	}
	for name, source := range fixtures {
		path := filepath.Join(root, filepath.FromSlash(name))
		if err := os.MkdirAll(filepath.Dir(path), 0o700); err != nil {
			t.Fatal(err)
		}
		if err := os.WriteFile(path, []byte(source), 0o600); err != nil {
			t.Fatal(err)
		}
	}
	for _, args := range [][]string{
		{"init"},
		{"add", ".gitignore", ".github/workflow.yml", "visible.py", "vendor/product/main.go"},
	} {
		command := exec.Command("git", args...)
		command.Dir = root
		if output, err := command.CombinedOutput(); err != nil {
			t.Fatalf("git %v: %v: %s", args, err, output)
		}
	}

	result, err := WalkWithMeta(root, 0)
	if err != nil {
		t.Fatal(err)
	}
	if result.DiscoveryMethod != "git_ls_files" {
		t.Fatalf("discovery method = %q, want git_ls_files", result.DiscoveryMethod)
	}
	indexed := map[string]bool{}
	for _, file := range result.Files {
		indexed[file.Path] = true
	}
	for _, path := range []string{".github/workflow.yml", "visible.py", "vendor/product/main.go"} {
		if !indexed[path] {
			t.Errorf("tracked product file %q was omitted (indexed=%v skipped=%v)", path, indexed, result.Skipped)
		}
	}
	if indexed["ignored.py"] {
		t.Error("gitignored untracked file must not be indexed")
	}
}

func TestWalkReceiptAccountsForEveryDiscoveredFile(t *testing.T) {
	root := t.TempDir()
	fixtures := map[string]string{
		"source.py":    "value = 1\n",
		"README.txt":   "not a registered source format\n",
		"LICENSE":      "not an extensionless source file\n",
		"generated.go": "// Code generated by test. DO NOT EDIT.\npackage fixture\n",
	}
	for name, source := range fixtures {
		if err := os.WriteFile(filepath.Join(root, name), []byte(source), 0o600); err != nil {
			t.Fatal(err)
		}
	}
	result, err := WalkWithMeta(root, 0)
	if err != nil {
		t.Fatal(err)
	}
	if result.FilesDiscovered != len(result.Files)+len(result.Skipped) {
		t.Fatalf("receipt does not account for discovery: discovered=%d files=%d skipped=%d", result.FilesDiscovered, len(result.Files), len(result.Skipped))
	}
	reasons := map[string]string{}
	for _, skipped := range result.Skipped {
		reasons[skipped.Path] = skipped.Reason
	}
	if reasons["README.txt"] != "unsupported_path" || reasons["LICENSE"] != "unsupported_path" || reasons["generated.go"] != "generated" {
		t.Fatalf("unexpected skip reasons: %v", reasons)
	}
}

func TestWalkDoesNotFollowSourceSymlinks(t *testing.T) {
	root := t.TempDir()
	target := filepath.Join(root, "target.py")
	link := filepath.Join(root, "linked.py")
	if err := os.WriteFile(target, []byte("def target():\n    return 1\n"), 0o600); err != nil {
		t.Fatal(err)
	}
	if err := os.Symlink(target, link); err != nil {
		t.Skipf("symlinks unavailable: %v", err)
	}

	result, err := WalkWithMeta(root, 0)
	if err != nil {
		t.Fatal(err)
	}
	for _, file := range result.Files {
		if file.Path == "linked.py" {
			t.Fatalf("source symlink gained graph authority: %+v", file)
		}
	}
	for _, skipped := range result.Skipped {
		if skipped.Path == "linked.py" && skipped.Reason == "non_regular_file" {
			return
		}
	}
	t.Fatalf("source symlink was not explicitly skipped: %+v", result.Skipped)
}
